def test_run_command_success(engine, mock_repo_path):
    """Tests successful execution of a git command."""
    with patch("subprocess.run") as mock_run:
        mock_run.return_value = MagicMock(
            returncode=0, stdout="success_out", stderr=""
        )
        code, out, err = engine._run_command(mock_repo_path, ["status"])
        
        assert code == 0
        assert out == "success_out"
        assert err == ""
        mock_run.assert_called_once_with(
            ["git", "-C", mock_repo_path, "status"],
            capture_output=True, text=True, timeout=30, check=False
        )

def test_run_command_timeout(engine, mock_repo_path):
    """Tests handling of subprocess timeout."""
    with patch("subprocess.run", side_effect=subprocess.TimeoutExpired("cmd", 30)):
        code, out, err = engine._run_command(mock_repo_path, ["fetch"])
        assert code == 124
        assert "timed out" in err

def test_verify_state_clean(engine, mock_repo_path):
    """Tests state verification for a clean working tree."""
    with patch.object(GitSkillEngine, "_run_command") as mock_run:
        # Mock porcelain status returning empty string (clean)
        mock_run.return_value = (0, "", "")
        assert engine._verify_state(mock_repo_path, "clean") is True
        
        # Mock porcelain status returning changes (dirty)
        mock_run.return_value = (0, "M file.txt", "")
        assert engine._verify_state(mock_repo_path, "clean") is False

