def test_handle_commit_flow_failure_rollback(engine, mock_repo_path):
    """Tests that a failed commit triggers a hard reset rollback."""
    with patch.object(GitSkillEngine, "_run_command") as mock_run:
        # Mock: add succeeds, commit fails
        mock_run.side_effect = [
            (0, "", ""),         # add
            (1, "", "commit error"), # commit
            (0, "", ""),         # reset --hard
        ]
        
        with pytest.raises(RuntimeError, match="Commit failed"):
            engine._handle_commit_flow(mock_repo_path, {"msg": "fail"}, {})
        
        # Verify rollback was called
        mock_run.assert_any_call(mock_repo_path, ["reset", "--hard", "HEAD"])

