def test_execute_full_success_cycle(engine, mock_repo_path):
    """End-to-end test of the execute method for a commit flow."""
    payload = {
        "action": GitAction.COMMIT_FLOW.value,
        "repo_path": mock_repo_path,
        "params": {"msg": "Integration test", "branch": "main"},
        "options": {"force": True}
    }
    
    with patch.object(GitSkillEngine, "_resolve_context", return_value=(True, "OK")), \
         patch.object(GitSkillEngine, "_handle_commit_flow", return_value={"commit_hash": "xyz"}), \
         patch.object(GitSkillEngine, "_verify_state", return_value=True):
        
        result = engine.execute(payload)
        
        assert result["status"] == "success"
        assert result["action_performed"] == "commit_flow"
        assert result["data"]["commit_hash"] == "xyz"
        assert "execution_time_ms" in result["telemetry"]

